ALTER TABLE `ymwl_admin`
    ADD COLUMN `wechat` VARCHAR(30) NOT NULL DEFAULT '' COMMENT '联系微信' AFTER `email`;
ALTER TABLE `ymwl_admin`
    CHANGE COLUMN `tel` `phone` VARCHAR(30) NOT NULL DEFAULT '' COMMENT '联系电话' COLLATE 'utf8mb4_unicode_ci' AFTER `realname`;
CREATE TABLE `ymwl_email_log` (
                                  `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
                                  `create_admin_id` INT(10) UNSIGNED NOT NULL DEFAULT '0' COMMENT '发送者',
                                  `create_username` VARCHAR(30) NOT NULL DEFAULT '' COMMENT '发送者用户名' COLLATE 'utf8mb4_unicode_ci',
                                  `email` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '收件箱' COLLATE 'utf8mb4_unicode_ci',
                                  `type` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '邮件类型：custome:客户,customer_contacts:客户联系人,client_order:订单,contract:合同' COLLATE 'utf8mb4_unicode_ci',
                                  `title` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '发送标题' COLLATE 'utf8mb4_unicode_ci',
                                  `content` TEXT NULL DEFAULT NULL COMMENT '发送内容' COLLATE 'utf8mb4_unicode_ci',
                                  `status` VARCHAR(50) NOT NULL DEFAULT 'success' COMMENT '状态' COLLATE 'utf8mb4_general_ci',
                                  `notes` VARCHAR(3000) NOT NULL DEFAULT '' COMMENT '备注' COLLATE 'utf8mb4_general_ci',
                                  `create_time` BIGINT(16) NULL DEFAULT '0' COMMENT '发送时间',
                                  PRIMARY KEY (`id`) USING BTREE
)
    COMMENT='邮件发送纪录表'
COLLATE='utf8mb4_unicode_ci'
ENGINE=MyISAM
ROW_FORMAT=DYNAMIC
;
CREATE TABLE `ymwl_emailtpl` (
                                 `id` smallint(6) unsigned NOT NULL AUTO_INCREMENT,
                                 `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '模板名称',
                                 `tpl_title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '模板标题',
                                 `tpl_content` text COLLATE utf8mb4_unicode_ci COMMENT '模板内容',
                                 `type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '模板类型',
                                 `status` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '状态 {radio} (0:禁用,1:启用)',
                                 `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
                                 `create_time` bigint(16) unsigned DEFAULT NULL COMMENT '创建时间',
                                 `update_time` bigint(16) unsigned DEFAULT NULL COMMENT '更新时间',
                                 PRIMARY KEY (`id`) USING BTREE,
                                 KEY `sort` (`sort`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='邮箱模板';

INSERT INTO `ymwl_emailtpl` (`id`, `name`, `tpl_title`, `tpl_content`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES
                                                                                                                                   (1,	'公司介绍',	'XXX信息技术有限公司 – 感谢您的关注',	'<title>XXX信息技术有限公司 – 感谢您的关注</title><table width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" bgcolor=\"#f5f7fa\"><tbody><tr class=\"firstRow\"><td align=\"center\"><!-- 主容器 --><table class=\"wrap\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:1200px;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 4px 12px rgba(0,0,0,.05);\"><!-- 顶部 --><tbody><tr class=\"firstRow\"><td style=\"background:#0052d9;color:#fff;padding:0 30px;height:70px;font-size:18px;font-weight:bold;\">XXX信息技术有限公司            <span style=\"float:right;font-size:14px;font-weight:normal;\">服务热线：400-089-8888</span></td></tr><!-- 内容区 --><tr><td style=\"padding:40px 30px 50px;\"><h2>亲爱的 {$customer_name}，<br>感谢您对 XXX 的关注！</h2><!-- 公司介绍 开始 --><p style=\"margin:0 0 15px;color:#555;line-height:1.8;\">我们是一家专注于 <strong>企业级数字化解决方案</strong> 的高新技术企业，12 年来已服务 <strong>3,200+</strong> 家行业龙头，帮助客户平均降低 <strong>27%</strong> 运营成本，缩短 <strong>40%</strong> 交付周期。</p><table cellpadding=\"0\" cellspacing=\"0\" style=\"margin:25px 0;width:100%;\"><tbody><tr class=\"firstRow\"><td width=\"33%\" valign=\"top\" style=\"padding-right:15px;\"><div style=\"background:#f0f6ff;border-left:4px solid #0052d9;padding:15px;\">                                                    <strong>01 / 技术领先</strong><br>50+ 项软件著作权，通过 ISO27001 &amp; CMMI5 认证。</div></td><td width=\"33%\" valign=\"top\" style=\"padding:0 7.5px;\"><div style=\"background:#f0f6ff;border-left:4px solid #0052d9;padding:15px;\">                                                    <strong>02 / 快速交付</strong><br>模块化平台 + 低代码，需求确认后 4 周即可上线。</div></td><td width=\"33%\" valign=\"top\" style=\"padding-left:15px;\"><div style=\"background:#f0f6ff;border-left:4px solid #0052d9;padding:15px;\">                                                    <strong>03 / 管家服务</strong><br>7×24 专属客户成功经理，SLA 99.9% 稳定运行。</div></td></tr></tbody></table><p style=\"margin:25px 0 0;color:#555;line-height:1.8;\">典型案例：<br>  • <strong>某全球 500 强零售集团</strong>：库存周转天数下降 18 天，年省资金占用 2.3 亿元；<br>  • <strong>某头部新能源车企</strong>：供应链协同平台让 600+ 家供应商一站式在线，采购效率 ↑55%。</p><p style=\"margin:30px 0 0;\">                                    <a href=\"https://www.80zx.com/\" target=\"_blank\" _href=\"https://www.80zx.com/\" textvalue=\"预约 30 分钟在线演示 →\" style=\"display: inline-block; background: rgb(0, 82, 217); color: rgb(255, 255, 255); padding: 12px 35px; border-radius: 4px; text-decoration: none; font-size: 16px;\">预约 30 分钟在线演示 →</a>​</p><!-- 公司介绍 结束 --></td></tr><!-- 底部 --><tr><td style=\"background:#f8f9fa;padding:20px 30px;font-size:12px;color:#888;line-height:1.6;\">本邮件由系统自动发送，请勿直接回复。<br>手机：158-8888-8888 | 座机：010-8888-8888 | QQ：3623820285<br>官网：<a href=\"https://www.80zx.com\" style=\"color:#0052d9;text-decoration:none;\">www.80zx.com</a></td></tr></tbody></table><!-- /主容器 --></td></tr></tbody></table>',	'customer',	1,	0,	1765176865,	1766304761),
                                                                                                                                   (2,	'合同到期提醒',	'合同即将到期，您需要续费了！',	'<table width=\"600\" style=\"width:600px !important;margin:0 auto !important;\n              font-size:14px !important;line-height:1.6 !important;\n              color:#333 !important;background:#fff !important;\n              border-spacing:0 !important; border-collapse:collapse !important;\"><tbody><tr class=\"firstRow\"><td style=\"background:#0052d9;color:#fff;padding:0 25px;height:60px;font-size:18px;font-weight:bold;\">\n                XXX信息技术有限公司 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<span style=\"font-size:14px;font-weight:normal;padding-left:20px;\">服务热线：400-089-xxxx</span></td></tr><!-- 主体 --><tr><td style=\"padding:30px 35px;color:#333;line-height:1.8;font-size:14px;\"><h2>\n                    尊敬的 {$customer_contact}，您好！</h2><p style=\"margin:0 0 15px;\">\n                    感谢您一直以来对 <strong>XXX信息技术有限公司</strong> 的信任与支持。</p><div style=\"background:#fff5e6;border-left:4px solid #ff9c2e;padding:15px 18px;margin:20px 0;font-size:15px;\">\n                    系统提示：贵我双方签署的 <strong>《{$contract_name}》</strong> 将于 &nbsp; &nbsp; &nbsp; <strong style=\"color:#d90000;\">{$contract_end_time}</strong>&nbsp;到期，为保证业务连续，请尽快办理续费/续约手续。</div><p style=\"margin:15px 0;\">\n                    续费仅需 2 步：</p><ol style=\"margin:10px 0;padding-left:20px;\" class=\" list-paddingleft-2\"><li><p>\n                            回复本邮件或致电专属客户经理zrwx978，确认续费方案；</p></li><li><p>\n                            收到我方电子合同/付款通知后完成付款，即可自动延期。</p></li></ol><p style=\"margin:20px 0 0;\">\n                    如需升级套餐或开具发票，也请直接联系，我们将第一时间为您处理。</p><!-- CTA --></td></tr><tr><td align=\"center\" style=\"background:#0052d9;border-radius:4px;\">                <a href=\"mailto:renew@80zx.com?subject=合同续费确认-{{客户编号}}\" style=\"display:block;color:#fff;padding:12px 35px;text-decoration:none;font-size:16px;\">立即回复确认续费</a></td></tr></tbody></table><!-